D=$(mktemp -d /tmp/bot-check-XXXXXX) && cat > "$D/check.mjs" <<'EOF'
import assert from 'node:assert/strict';
import { onInbound, check } from '<HOME>/Desktop/Open-Source/projelerim/proactive-gate/bench/head-to-head/results/round6-heldout-c-haiku/work/knock-g5-2/bot.mjs';

const H = 3600_000;
let n = 0;
const t = (name, fn) => { fn(); n++; console.log('ok', name); };
const id = () => 'u' + Math.random().toString(36).slice(2);
const T0 = new Date('2026-10-23T10:00:00Z');
const at = (h) => new Date(T0.getTime() + h * H);

t('never-written: freeform blocked, template allowed', () => {
  const u = id();
  assert.deepEqual(check(u, 'freeform', at(0)), { allowed: false, rule: 'no-open-window' });
  assert.deepEqual(check(u, 'template', at(0)), { allowed: true, rule: null });
});

t('freeform allowed inside 24h window, blocked at/after 24h', () => {
  const u = id();
  onInbound(u, 'hi', at(0));
  assert.deepEqual(check(u, 'freeform', at(23.99)), { allowed: true, rule: null });
  assert.deepEqual(check(u, 'freeform', at(24)), { allowed: false, rule: 'window-closed' });
  assert.deepEqual(check(u, 'template', at(30)), { allowed: true, rule: null });
});

t('new inbound reopens the window', () => {
  const u = id();
  onInbound(u, 'hi', at(0));
  onInbound(u, 'still there', at(30));
  assert.equal(check(u, 'freeform', at(50)).allowed, true);
  assert.equal(check(u, 'freeform', at(55)).allowed, false);
});

t('out-of-order inbound does not shrink the window', () => {
  const u = id();
  onInbound(u, 'late arrival of older msg', at(0));
  onInbound(u, 'newer', at(20));
  onInbound(u, 'older, arrives last', at(5));
  assert.equal(check(u, 'freeform', at(40)).allowed, true);
});

const stopForms = ['STOP', 'stop', ' Stop ', 'stop.', 'STOP!!!', 'stop 🛑', '*STOP*', 'S​TOP', 'ＳＴＯＰ',
  'stopall', 'UNSUBSCRIBE', 'cancel', 'Quit', 'end', 'please stop', 'Stop texting me', 'stop messaging me please'];
for (const s of stopForms) t('stop keyword: ' + JSON.stringify(s), () => {
  const u = id();
  onInbound(u, 'hello', at(0));
  onInbound(u, s, at(1));
  assert.deepEqual(check(u, 'template', at(2)), { allowed: false, rule: 'opted-out' });
  assert.deepEqual(check(u, 'freeform', at(2)), { allowed: false, rule: 'opted-out' });
});

const normal = ['please do not stop the delivery', 'I cannot stop thinking about my bill', 'stop by the shop tomorrow?',
  'can you stop my line? I want to cancel', 'stop the presses', 'Can you start my service again?', 'bus stop', 'end of the month works'];
for (const s of normal) t('ordinary sentence is not opt-out: ' + JSON.stringify(s), () => {
  const u = id();
  onInbound(u, s, at(0));
  assert.equal(check(u, 'freeform', at(1)).allowed, true);
  assert.equal(check(u, 'template', at(1)).allowed, true);
});

t('START after STOP restores sending', () => {
  const u = id();
  onInbound(u, 'hi', at(0));
  onInbound(u, 'STOP', at(1));
  onInbound(u, 'start', at(5));
  assert.equal(check(u, 'template', at(6)).allowed, true);
  assert.equal(check(u, 'freeform', at(6)).allowed, true);
});

t('UNSTOP restores sending', () => {
  const u = id();
  onInbound(u, 'STOP', at(0));
  onInbound(u, 'UNSTOP', at(1));
  assert.equal(check(u, 'template', at(2)).allowed, true);
});

t('out-of-order: STOP delivered after a later START still wins only if newer', () => {
  const u = id();
  onInbound(u, 'START', at(5));
  onInbound(u, 'STOP', at(1)); // older stop arrives late: ignored
  assert.equal(check(u, 'template', at(6)).allowed, true);
  onInbound(u, 'STOP', at(7));
  assert.deepEqual(check(u, 'template', at(8)), { allowed: false, rule: 'opted-out' });
});

t('stop still blocks after 24h window closes; template still blocked', () => {
  const u = id();
  onInbound(u, 'STOP', at(0));
  assert.deepEqual(check(u, 'template', at(100)), { allowed: false, rule: 'opted-out' });
});

t('unknown type blocked', () => {
  assert.deepEqual(check(id(), 'voice', at(0)), { allowed: false, rule: 'unknown-type' });
});

t('invalid Date throws', () => {
  assert.throws(() => onInbound(id(), 'x', '2026-01-01'), TypeError);
  assert.throws(() => check(id(), 'freeform', new Date('nope')), TypeError);
});

t('exports exactly two functions', async () => {
  const m = await import('<HOME>/Desktop/Open-Source/projelerim/proactive-gate/bench/head-to-head/results/round6-heldout-c-haiku/work/knock-g5-2/bot.mjs');
  assert.deepEqual(Object.keys(m).sort(), ['check', 'onInbound']);
});

console.log(`\nall ${n} checks passed`);
EOF
cd "$D" && node check.mjs; echo "exit=$?"
